import { useMemo } from "preact/hooks";
import { useParsedData, useWidgetEvents } from "../../shared/lib/lifecycle.js";
import { useStore } from "../../shared/lib/store.js";
import { createMarketStore } from "./lib/state.js";
import { normalizeStream } from "./lib/normalize.js";
import { t } from "./lib/i18n.js";
import { GroupTab, QuoteRow, TableHead } from "./components.js";
import s from "./styles/stream.css";
import v from "./generated/variables.css";

export const TAG = "np-market-stream";

function MarketStream({ model }) {
    const controller = useMemo(() => createMarketStore(model), [model]);
    const { store } = controller;
    const activeId = useStore(store, (state) => state.activeId);
    const shownId = useStore(store, (state) => state.shownId);
    const loading = useStore(store, (state) => state.loading);
    const revision = useStore(store, (state) => state.revision);
    const ref = useWidgetEvents(TAG, revision);
    const group = store.getState().groups[shownId];

    function onKeyDown(event, id) {
        const next = controller.moveSelection(id, event.key);
        if (!next)
            return;
        event.preventDefault();
        controller.selectGroup(next);
        ref.current?.querySelector(`#mks-tab-${next}`)?.focus();
    }

    return (
        <div class={`${v.additional} ${s.root}`} ref={ref} data-loading={loading ? "true" : "false"}>
            <header class={s.header}>
                <h2 class={s.title}>{t("market.title")}</h2>
                <time class={s.updated} dateTime={new Date(model.now).toISOString()}>{t("market.updated", { time: model.updated })}</time>
            </header>
            <div class={s.tabs} role="tablist" aria-label={t("market.groups")}>
                {model.tabs.map((tab) => (
                    <GroupTab key={tab.id} tab={tab} selected={tab.id === activeId} onSelect={controller.selectGroup} onKeyDown={onKeyDown} />
                ))}
            </div>
            <div class={s.panel} id="mks-panel" role="tabpanel" aria-labelledby={`mks-tab-${activeId}`} aria-busy={loading ? "true" : "false"}>
                <div class={s.summary}>
                    <span aria-live="polite">{t("market.summary", { up: group.up, down: group.down })}</span>
                </div>
                <TableHead />
                <ul class={s.list}>
                    {group.rows.map((row, index) => (
                        <QuoteRow key={row.id} row={row} tone={index % 10} />
                    ))}
                </ul>
            </div>
            <footer class={s.footer}>
                <p class={s.disclaimer}>{t("market.disclaimer")}</p>
                <a class={s.all} href="/finanzen">{t("market.all")}</a>
            </footer>
        </div>
    );
}

export function Widget({ dataJson }) {
    const data = useParsedData(dataJson);
    const model = useMemo(() => (data ? normalizeStream(data) : null), [data]);
    return model ? <MarketStream model={model} /> : null;
}
