const LOCALE = "de-DE";
const TIME_ZONE = "Europe/Berlin";
const cache = new Map();

function formatter(kind, options) {
    const key = kind + JSON.stringify(options);
    let instance = cache.get(key);
    if (!instance) {
        instance = kind === "date" ? new Intl.DateTimeFormat(LOCALE, { timeZone: TIME_ZONE, ...options }) : new Intl.NumberFormat(LOCALE, options);
        cache.set(key, instance);
    }
    return instance;
}

export function formatNumber(value, digits = 2) {
    return formatter("number", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
}

export function formatSigned(value, digits = 2) {
    return formatter("number", { minimumFractionDigits: digits, maximumFractionDigits: digits, signDisplay: "exceptZero" }).format(value);
}

export function formatPercent(fraction, digits = 2) {
    return formatter("number", { style: "percent", minimumFractionDigits: digits, maximumFractionDigits: digits, signDisplay: "exceptZero" }).format(fraction);
}

export function formatCompact(value) {
    return formatter("number", { notation: "compact", maximumFractionDigits: 1 }).format(value);
}

export function formatTime(timestamp) {
    return formatter("date", { hour: "2-digit", minute: "2-digit" }).format(timestamp);
}

export function formatShortDate(timestamp) {
    return formatter("date", { day: "2-digit", month: "2-digit" }).format(timestamp);
}

export function formatWeekday(timestamp) {
    return formatter("date", { weekday: "short" }).format(timestamp);
}

export function formatLongDate(timestamp) {
    return formatter("date", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(timestamp);
}

export function formatDateTime(timestamp) {
    return formatter("date", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }).format(timestamp);
}

export function dayKey(timestamp) {
    return formatter("date", { year: "numeric", month: "2-digit", day: "2-digit" }).format(timestamp);
}

const UNITS = [["day", 86400000], ["hour", 3600000], ["minute", 60000]];

export function formatRelative(now, timestamp) {
    const delta = timestamp - now;
    const rtf = formatter("rtf", {});
    for (const [unit, size] of UNITS) {
        if (Math.abs(delta) >= size || unit === "minute")
            return rtf.format(Math.round(delta / size), unit);
    }
    return "";
}

cache.set("rtf{}", new Intl.RelativeTimeFormat(LOCALE, { numeric: "auto" }));

export function currentTime(data) {
    return globalThis.__portal?.now ?? Date.parse(data.now);
}
