export const SPARK_WIDTH = 96;
export const SPARK_HEIGHT = 28;
const PADDING = 2;

function round(value) {
    return Math.round(value * 10) / 10;
}

// Builds the SVG path data for a line and its filled area, plus the end point.
export function buildSparkline(points, width = SPARK_WIDTH, height = SPARK_HEIGHT) {
    const values = points.map((point) => point.v);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const span = max - min || 1;
    const last = points.length - 1;
    const coords = points.map((point, index) => [
        round(PADDING + (index / last) * (width - 2 * PADDING)),
        round(height - PADDING - ((point.v - min) / span) * (height - 2 * PADDING)),
    ]);
    const line = coords.map(([x, y], index) => `${index === 0 ? "M" : "L"}${x} ${y}`).join("");
    const area = `${line}L${coords[last][0]} ${height}L${coords[0][0]} ${height}z`;
    return { line, area, end: coords[last] };
}

export function downsample(points, maxPoints) {
    if (points.length <= maxPoints)
        return points;
    const step = (points.length - 1) / (maxPoints - 1);
    return Array.from({ length: maxPoints }, (_, index) => points[Math.round(index * step)]);
}
