const PLURAL_RE = /\{(\w+),\s*plural,\s*one\s*\{([^}]*)\}\s*other\s*\{([^}]*)\}\s*\}/g;
const PARAM_RE = /\{(\w+)\}/g;

export function createTranslator(tables, locale = "de", fallbackLocale = "en") {
    const primary = tables[locale] || {};
    const fallback = tables[fallbackLocale] || {};
    const rules = new Intl.PluralRules(locale === "de" ? "de-DE" : locale);

    function t(key, params) {
        let message = primary[key] ?? fallback[key];
        if (message === undefined)
            return key;
        if (!params)
            return message;
        message = message.replace(PLURAL_RE, (_, name, one, other) => (rules.select(Number(params[name])) === "one" ? one : other));
        return message.replace(PARAM_RE, (whole, name) => (name in params ? String(params[name]) : whole));
    }

    t.has = (key) => key in primary || key in fallback;
    return t;
}
