import { memo } from "preact/compat";
import { SPARK_HEIGHT, SPARK_WIDTH } from "./lib/sparkline.js";
import { t } from "./lib/i18n.js";
import s from "./styles/stream.css";
import v from "./generated/variables.css";

const ARROWS = { up: "M2 8l4-5 4 5", down: "M2 4l4 5 4-5", flat: "M2 6h8" };

export const Sparkline = memo(function Sparkline({ spark, trend }) {
    return (
        <svg class={s.spark} data-trend={trend} viewBox={`0 0 ${SPARK_WIDTH} ${SPARK_HEIGHT}`} width={SPARK_WIDTH} height={SPARK_HEIGHT} role="img" aria-label={t("market.sparkLabel")}>
            <path class={s.sparkArea} d={spark.area} />
            <path class={s.sparkLine} d={spark.line} fill="none" />
            <circle class={s.sparkEnd} cx={spark.end[0]} cy={spark.end[1]} r="2" />
        </svg>
    );
});

function Arrow({ trend }) {
    return (
        <svg class={s.arrow} viewBox="0 0 12 12" width="12" height="12" aria-hidden="true" focusable="false">
            <path d={ARROWS[trend]} fill="none" stroke="currentColor" stroke-width="1.6" />
        </svg>
    );
}

export const QuoteRow = memo(function QuoteRow({ row, tone }) {
    return (
        <li class={`${s.row} ${v.accent}`} data-trend={row.trend} data-tone={tone}>
            <a class={s.link} href={row.href} aria-label={row.label} title={row.venue}>
                <span class={s.name}>{row.name}</span>
                <span class={s.isin}>{row.isin}</span>
                <span class={s.value}>{row.value}</span>
                <span class={s.change}>
                    <Arrow trend={row.trend} />
                    {row.change}
                </span>
                <span class={s.percent}>{row.percent}</span>
                <Sparkline spark={row.spark} trend={row.trend} />
                <span class={s.low} title={t("market.low")}>{row.low}</span>
                <span class={s.high} title={t("market.high")}>{row.high}</span>
                <time class={s.time} dateTime={row.iso}>{row.time}</time>
            </a>
        </li>
    );
});

export const GroupTab = memo(function GroupTab({ tab, selected, onSelect, onKeyDown }) {
    return (
        <button class={`${s.tab} ${v.link}`} type="button" role="tab" id={`mks-tab-${tab.id}`} aria-selected={selected ? "true" : "false"} aria-controls="mks-panel" tabIndex={selected ? 0 : -1} data-tone={tab.tone} onClick={() => onSelect(tab.id)} onKeyDown={(event) => onKeyDown(event, tab.id)}>
            {tab.label}
        </button>
    );
});

export const TableHead = memo(function TableHead() {
    return (
        <div class={s.head} aria-hidden="true">
            <span>{t("market.name")}</span>
            <span>{t("market.last")}</span>
            <span>{t("market.change")}</span>
            <span>{t("market.trend")}</span>
        </div>
    );
});
