import { createStore } from "../../../shared/lib/store.js";
import { fetchJson } from "../../../shared/lib/fetcher.js";
import { normalizeGroup } from "./normalize.js";

const API = "data/api/widgets/market";

export function createMarketStore(model) {
    const store = createStore({ activeId: model.activeId, shownId: model.activeId, groups: { [model.activeId]: model.initialGroup }, loading: false, revision: 0 });
    let token = 0;

    async function loadHistory(id) {
        const current = ++token;
        store.setState({ loading: true });
        try {
            const payload = await fetchJson(`${API}/${id}.json`);
            if (current !== token)
                return;
            store.setState((state) => ({ loading: false, shownId: id, groups: { ...state.groups, [id]: normalizeGroup(payload.group) }, revision: state.revision + 1 }));
        } catch (error) {
            console.error("[np-market-stream] could not load group", error);
            if (current === token)
                store.setState({ loading: false });
        }
    }

    return {
        store,
        selectGroup(id) {
            const state = store.getState();
            if (id === state.activeId)
                return;
            store.setState({ activeId: id, shownId: state.groups[id] ? id : state.shownId, revision: state.revision + 1 });
            if (!state.groups[id])
                loadHistory(id);
        },
        moveSelection(id, key) {
            const index = model.tabs.findIndex((tab) => tab.id === id);
            const count = model.tabs.length;
            const next = key === "ArrowRight" ? (index + 1) % count : key === "ArrowLeft" ? (index + count - 1) % count : key === "Home" ? 0 : key === "End" ? count - 1 : -1;
            return next < 0 ? null : model.tabs[next].id;
        },
    };
}
