import { assertValid, unwrapConnection } from "../../../shared/lib/validate.js";
import { formatNumber, formatPercent, formatSigned, formatTime } from "../../../shared/lib/format.js";
import { lookup } from "../generated/directory.js";
import { buildSparkline, downsample } from "./sparkline.js";
import { schemas } from "./schema.js";
import { t } from "./i18n.js";

function direction(change) {
    return change > 0 ? "up" : change < 0 ? "down" : "flat";
}

function quoteDigits(kind) {
    return kind === "currency" ? 4 : 2;
}

function normalizeIndex(node, kind, position) {
    const quote = node.quote;
    const digits = quoteDigits(kind);
    const trend = direction(quote.change);
    const spark = buildSparkline(downsample(quote.sparkline.points, 32));
    const listing = lookup(position + 1);
    return {
        id: node.id,
        name: node.name,
        isin: node.isin,
        venue: listing ? listing[1] : "",
        href: `/finanzen/indizes/${node.isin.toLowerCase()}`,
        value: formatNumber(quote.last, digits),
        change: formatSigned(quote.change, digits),
        percent: formatPercent(quote.changePercent / 100),
        high: formatNumber(quote.high, digits),
        low: formatNumber(quote.low, digits),
        time: formatTime(Date.parse(quote.updatedAt)),
        iso: quote.updatedAt,
        trend,
        spark,
        label: t("market.rowLabel", { name: node.name, value: formatNumber(quote.last, digits), currency: node.currency, change: formatSigned(quote.changePercent, 2), direction: t(`market.${trend}`) }),
    };
}

export function normalizeGroup(group) {
    const rows = unwrapConnection(group.indices).map((node, index) => normalizeIndex(node, group.kind, index));
    return {
        id: group.id,
        label: group.label,
        rows,
        up: rows.filter((row) => row.trend === "up").length,
        down: rows.filter((row) => row.trend === "down").length,
    };
}

export function normalizeStream(raw) {
    assertValid(schemas, "MarketStream", raw);
    return {
        id: raw.id,
        now: Date.parse(raw.now),
        updated: formatTime(Date.parse(raw.now)),
        activeId: raw.activeGroupId,
        tabs: raw.groups.map((group, index) => ({ id: group.id, label: group.label, tone: index })),
        initialGroup: normalizeGroup(raw.activeGroup),
    };
}
